 const wall=$('#gallery-wall'),bar=document.createElement('div');bar.className='motion-album-tools';bar.innerHTML='<div role="group" aria-label="相册呈现方式"><button type="button" data-album-mode="pile" aria-pressed="true">叠放翻阅</button><button type="button" data-album-mode="wall" aria-pressed="false">铺开看</button></div><div><button type="button" data-album-prev aria-label="翻到上一张照片">上一张</button><span data-album-count role="status"></span><button type="button" data-album-next aria-label="翻到下一张照片">下一张</button></div><p>左右拨动最上面的照片；轻点可展开，照片内容与相册保持对应。</p>';wall.before(bar);let cards=[],index=0,mode='pile',drag=null,busy=false,consumeUntil=0;
 function draw(){wall.classList.toggle('motion-pile',mode==='pile');cards.forEach((card,i)=>{const rank=(i-index+cards.length)%cards.length;card.dataset.pileRank=String(rank);card.style.setProperty('--pile-rank',rank);card.style.setProperty('--pile-tilt',([-3,4,-5,2][rank%4])+'deg');card.inert=mode==='pile'&&rank!==0;card.classList.toggle('motion-front',rank===0);card.style.visibility=mode==='pile'&&rank>3?'hidden':'';});$('[data-album-count]',bar).textContent=cards.length?`${index+1} / ${cards.length} 张`:'暂无照片';$$('[data-album-mode]',bar).forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.albumMode===mode)));$('[data-album-prev]',bar).disabled=busy||cards.length<2;$('[data-album-next]',bar).disabled=busy||cards.length<2;}
 function reset(){cards=$$('.gallery-photo',wall);index=0;drag=null;busy=false;draw();}
 function turn(direction=1,initialX=0){if(busy||cards.length<2)return;const card=cards[index],restoreFocus=card.contains(document.activeElement);busy=true;draw();const finish=()=>{card.classList.remove('is-pile-dragging');card.style.removeProperty('--drag-x');card.style.removeProperty('--drag-y');card.style.removeProperty('--drag-rotation');index=(index+direction+cards.length)%cards.length;busy=false;draw();if(restoreFocus)cards[index].focus({preventScroll:true});};
  if(reduce.matches){finish();return;}card.classList.add('is-pile-dragging');card.style.setProperty('--drag-x',initialX+'px');const origin=initialX,started=performance.now(),duration=430;
  function frame(now){if(!busy)return;const t=Math.min(1,(now-started)/duration),x=origin+direction*ease(t)*500;card.style.setProperty('--drag-x',x+'px');card.style.setProperty('--drag-y',(-Math.sin(t*Math.PI)*35)+'px');card.style.setProperty('--drag-rotation',(x*.035)+'deg');card.style.setProperty('--drag-alpha',String(1-t*.9));if(t<1)requestAnimationFrame(frame);else{card.style.removeProperty('--drag-alpha');finish();}}
  requestAnimationFrame(frame);
 }
 bar.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.albumMode){mode=b.dataset.albumMode;draw();}else if(b.hasAttribute('data-album-next'))turn(1);else if(b.hasAttribute('data-album-prev'))turn(-1);});
 wall.addEventListener('dragstart',e=>e.preventDefault());wall.addEventListener('pointerdown',e=>{const card=e.target.closest('.gallery-photo');if(mode!=='pile'||busy||card!==cards[index]||e.button!==0)return;drag={id:e.pointerId,card,x:e.clientX,y:e.clientY,dx:0,dy:0,moved:false};card.setPointerCapture(e.pointerId);});
 wall.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;drag.dx=e.clientX-drag.x;drag.dy=e.clientY-drag.y;if(Math.hypot(drag.dx,drag.dy)<7&&!drag.moved)return;drag.moved=true;e.preventDefault();drag.card.classList.add('is-pile-dragging');drag.card.style.setProperty('--drag-x',drag.dx+'px');drag.card.style.setProperty('--drag-y',drag.dy*.3+'px');drag.card.style.setProperty('--drag-rotation',Math.max(-15,Math.min(15,drag.dx*.04))+'deg');});
 function release(cancel=false){if(!drag)return;const d=drag;drag=null;if(!d.moved)return;consumeUntil=performance.now()+220;if(!cancel&&Math.abs(d.dx)>65){turn(d.dx>0?1:-1,d.dx);return;}d.card.classList.remove('is-pile-dragging');d.card.style.removeProperty('--drag-x');d.card.style.removeProperty('--drag-y');d.card.style.removeProperty('--drag-rotation');}
 wall.addEventListener('pointerup',()=>release());wall.addEventListener('pointercancel',()=>release(true));wall.addEventListener('click',e=>{if(performance.now()<consumeUntil){e.preventDefault();e.stopImmediatePropagation();}},true);wall.addEventListener('keydown',e=>{if(mode!=='pile')return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();turn(e.key==='ArrowRight'?1:-1);}});new MutationObserver(reset).observe(wall,{childList:true});disposers.add(()=>{release(true);if(busy){busy=false;cards.forEach(card=>{card.classList.remove('is-pile-dragging');['--drag-x','--drag-y','--drag-rotation','--drag-alpha'].forEach(p=>card.style.removeProperty(p));});draw();}});reset();
